local _,AUI=...
-- Original RUI hub routes. Identity/level facts checked against installed Forever 1.60.1 QuestieDB metadata.
AUI.CreateAuthoredGuides=function()return {{["id"]="elwynn",["name"]="Elwynn Forest",["faction"]="Alliance",["min"]=1,["max"]=10,["area"]=12,["hubs"]={{["name"]="Northshire",["min"]=1,["max"]=5,["quests"]={7,15,21,18,6,54},["note"]="Begin with the abbey and Echo Ridge. Clear the kobold chain before pushing into the vineyard. Garrick is a named target: pull him away from nearby thieves. Finish the report to Goldshire before leaving."},{["name"]="Goldshire and the mines",["min"]=5,["max"]=7,["quests"]={60,47,62,76},["note"]="Take Candles and Gold Dust together. Work Fargodeep first; keep collecting both drops while checking the mine. Visit Jasperlode after the southern farm circuit, then return to Goldshire."},{["name"]="Southern farms",["min"]=6,["max"]=8,["quests"]={85,86,84,87,88},["note"]="Follow the necklace conversation through Billy before hunting Goldtooth. Keep boar meat for the pie. Princess has escorts; clear a safe pull before engaging."},{["name"]="Eastvale and the river",["min"]=7,["max"]=10,["quests"]={35,37,45,39,46,52,5545,91732},["note"]="Move east along the road to the guard bridge and Eastvale. Combine murloc work with the lost-guard search, collect bundles of wood nearby, and complete Good Steel where the live objective markers lead. Return reports before moving west."},{["name"]="Westbrook and departure",["min"]=9,["max"]=10,["quests"]={239,11,176,109},["note"]="Use Westbrook as the final Elwynn hub. Hogger is optional group content: skip this guide task if a safe group is unavailable. Report toward Westfall once the local loop is finished."}}},{["id"]="dun-morogh",["name"]="Dun Morogh",["faction"]="Alliance",["min"]=1,["max"]=10,["area"]=1,["hubs"]={{["name"]="Coldridge Valley",["min"]=1,["max"]=5,["quests"]={179,233,234,183,170,182,218,282},["note"]="Follow the valley delivery route while clearing boars, wolves and troggs. Visit the troll cave after its pickup; collect the journal before reporting through the tunnel."},{["name"]="Kharanos and Steelgrill",["min"]=5,["max"]=7,["quests"]={400,317,313,5541},["note"]="Set your home at Kharanos, learn skills and visit Steelgrill. Combine bear/wolf collection with the grizzled den and deliver ammunition on the same western loop."},{["name"]="Brewnall and Shimmer Ridge",["min"]=6,["max"]=9,["quests"]={318,319,320,315,308,310,311},["note"]="Work Evershine and the nearby troll camps before returning to Kharanos. Finish the stout conversation in order; obtain the requested drink when the current step asks for it."},{["name"]="Gol Bolar and Frostmane",["min"]=8,["max"]=10,["quests"]={432,433,287,412,95041},["note"]="Clear the quarry and recover the Forever data objective where live markers place it. Do Frostmane from the entrance outward; avoid pulling deep cave packs at low level."},{["name"]="Eastern road",["min"]=9,["max"]=10,["quests"]={419,417,413,414},["note"]="Check the lost-pilot chain, then carry stout toward Loch Modan. If the named revenge target is unsafe, skip it and use the southern road into the next zone."}}},{["id"]="teldrassil",["name"]="Teldrassil",["faction"]="Alliance",["min"]=1,["max"]=10,["area"]=141,["hubs"]={{["name"]="Shadowglen",["min"]=1,["max"]=5,["quests"]={456,457,458,459,916,3521,4495},["note"]="Stay in Shadowglen through the balance and spider tasks. Collect antidote ingredients while moving between the cave and nearby plants, then deliver the aid before going to Dolanaar."},{["name"]="Dolanaar",["min"]=5,["max"]=7,["quests"]={2159,488,489,997,918,919,2438,2459},["note"]="Make Dolanaar the hub. Combine timberling collection with the lake visit and the dreamcatcher chain. Zenn's follow-up belongs after his first turn-in."},{["name"]="Ban'ethil",["min"]=7,["max"]=9,["quests"]={475,476,483,2541,2561},["note"]="Take the Gnarlpine and barrow tasks before entering Ban'ethil. Clear one corridor at a time, collect the relics while inside, and keep the sleeping-druid chain in sequence."},{["name"]="Northern forest",["min"]=9,["max"]=10,["quests"]={487,932,937,930,931,2399},["note"]="Use the road patrol before heading north. Visit the corrupted cave and enchanted glade with room to retreat; complete the fruit/frond pickups on this circuit."},{["name"]="Denalan and departure",["min"]=9,["max"]=10,["quests"]={2498,2499,922,923,940},["note"]="Finish the timberling reports and Denalan's named target. Report toward Darnassus, train, and travel to Auberdine for the next route."}}},{["id"]="durotar",["name"]="Durotar",["faction"]="Horde",["min"]=1,["max"]=10,["area"]=14,["hubs"]={{["name"]="Valley of Trials",["min"]=1,["max"]=5,["quests"]={788,790,804,789},["note"]="Clear boars and scorpids while completing Sarkoth's report chain. Stay near the valley until your starting skills and local turn-ins are finished."},{["name"]="Sen'jin and the coast",["min"]=5,["max"]=8,["quests"]={823,784,791,825,818,817,815},["note"]="Visit Sen'jin and Razor Hill to gather the coastal tasks. Clear Tiragarde first, collect supplies from wrecks, and combine crab/crawler drops with the beach loop."},{["name"]="Echo Isles",["min"]=7,["max"]=10,["quests"]={808,826,97225},["note"]="Take the island tasks together before crossing. Work around the outer isles first, recover the skull and recorded Forever idols, then approach Zalazane only with a clean retreat."},{["name"]="Razor Hill and inland camps",["min"]=8,["max"]=10,["quests"]={837,834,835,812,813},["note"]="Return to Razor Hill, then make an inland circuit through quillboar and harpy territory. Keep the cure/antidote chain together and use the live markers for its collection."},{["name"]="Northern road",["min"]=9,["max"]=10,["quests"]={806,828,827,829,840,842},["note"]="Visit Margoz before Skull Rock. The cave and named caster can be dangerous at ten; skip unsafe tasks rather than forcing them. Deliver the reports and take Crossroads conscription into the Barrens."}}},{["id"]="mulgore",["name"]="Mulgore",["faction"]="Horde",["min"]=1,["max"]=10,["area"]=215,["hubs"]={{["name"]="Red Cloud Mesa",["min"]=1,["max"]=5,["quests"]={747,750,752,753,755,757},["note"]="Complete the hunt and water errands before entering the quillboar camp. Gather the rite items on that visit and report before descending to Bloodhoof."},{["name"]="Bloodhoof Village",["min"]=5,["max"]=7,["quests"]={748,754,745,761,767,771,772},["note"]="Use Bloodhoof as your home hub. Combine wolf/swoop collection with the well-cleansing chain and follow the vision before the next rite."},{["name"]="Windfury and the caravan",["min"]=7,["max"]=9,["quests"]={743,749,751,756,758,766},["note"]="Visit the caravan, keep the follow-up clue, and combine harpies with the next totem materials. Mazzranache is a roaming target: pursue only when encountered safely."},{["name"]="Venture Co. and Wildmane",["min"]=9,["max"]=10,["quests"]={764,765,759,760,98424},["note"]="Finish the eastern mine tasks and its Forever notes before returning. Clear the named supervisor carefully; gather the final well materials during the same circuit."},{["name"]="Thunder Bluff and departure",["min"]=10,["max"]=10,["quests"]={773,775,833,854},["note"]="Finish the rite reports and burial visit, train in Thunder Bluff, then take the road through the Barrens toward the Crossroads."}}},{["id"]="tirisfal",["name"]="Tirisfal Glades",["faction"]="Horde",["min"]=1,["max"]=10,["area"]=85,["hubs"]={{["name"]="Deathknell",["min"]=1,["max"]=5,["quests"]={363,364,376,380,6395},["note"]="Work outward from the chapel, then enter Night Web's Hollow after its pickup. Complete Marla's requested remains on the same graveyard loop before leaving Deathknell."},{["name"]="Brill and the farms",["min"]=5,["max"]=7,["quests"]={404,365,407,367,374,427},["note"]="Make Brill your hub. Combine field work, putrid drops and the first plague collection while clearing the nearby Scarlet camps. Turn in before advancing the chains."},{["name"]="Agamand Mills",["min"]=7,["max"]=9,["quests"]={361,354,362,426,398},["note"]="Read the dropped letter if it is available, then gather the mills objectives together. Work the named family targets and Maggot Eye after clearing nearby enemies."},{["name"]="Scarlet perimeter",["min"]=8,["max"]=10,["quests"]={370,371,372,368,369,492},["note"]="Follow each Scarlet and plague stage in order. Bring the requested drops back before expecting the next pickup; do not push into a higher-stage camp simply because it is visible."},{["name"]="Final reports and Silverpine",["min"]=9,["max"]=10,["quests"]={359,360,375,355,445},["note"]="Complete the western/eastern reports, gather the cold-of-death supplies when requested, then carry the Silverpine delivery through the Undercity approach."}}},{["id"]="westfall",["name"]="Westfall",["faction"]="Alliance",["min"]=10,["max"]=20,["area"]=40,["hubs"]={{["name"]="Roadside farms",["min"]=10,["max"]=12,["quests"]={36,64,151},["note"]="Take the roadside and farm-family pickups before reaching Sentinel Hill. Keep oats, vulture meat, murloc eyes and goretusk snouts when the live tasks ask for them; finish the nearby fields on the road south."},{["name"]="Sentinel Hill and northern farms",["min"]=12,["max"]=14,["quests"]={9,12,102,153,92742,92909,92910,92911},["note"]="Set up Sentinel Hill and take the militia/farm work together. Clear northern farms and gather machinery drops along the way. Check both farm wells while combining harvester objectives; already-completed quests skip automatically."},{["name"]="Coast and murlocs",["min"]=13,["max"]=15,["quests"]={22,38,103,104},["note"]="Make a coastal loop for shore creatures and murloc objectives, keeping required drops rather than farming each separately. Return to Sentinel Hill before accepting later Defias stages."},{["name"]="Defias reports",["min"]=14,["max"]=17,["quests"]={65,132,135,141,142},["note"]="Follow the Defias intelligence trail through each report. City visits are a chance to train and buy upcoming route supplies; return along the road rather than crossing dense camps."},{["name"]="Southern fields and Deadmines preparation",["min"]=17,["max"]=20,["quests"]={13,14,155,152,92747,92748,92749,92750,92751,92752},["note"]="Work the southern militia stage with patrol routes in mind. Deadmines is optional: use the Dungeon manager to track its pickups and share held quests. Finish available Westfall reports before choosing Redridge or another next zone."}}},{["id"]="loch-modan",["name"]="Loch Modan",["faction"]="Alliance",["min"]=10,["max"]=20,["area"]=38,["hubs"]={{["name"]="Southern pass and Thelsamar",["min"]=10,["max"]=12,["quests"]={224,267,416,418,6387,6388,6391,6392},["note"]="Gather the south-pass defence work and move to Thelsamar. Set your home, unlock the flight connection and gather meat while clearing the road-side troggs."},{["name"]="Northern watch",["min"]=12,["max"]=14,["quests"]={1339,307,1338},["note"]="Take Stormpike's orders and work the north mine. Collect rat ears when applicable and complete Filthy Paws in one cautious mine visit."},{["name"]="Eastern shore",["min"]=13,["max"]=16,["quests"]={385,2038,436,298,301,302},["note"]="Visit the eastern hunting and excavation hubs together. Recover Bingles' tools along the shore, then report excavation progress before attempting its next stage."},{["name"]="Shipment and quarry",["min"]=15,["max"]=18,["quests"]={309,454,86613},["note"]="Clear the approach before protecting the shipment. Escort tasks are optional if a group cannot safely start them; gather the Forever excavation tools where the live objectives place them."},{["name"]="Final hunts",["min"]=18,["max"]=20,["quests"]={531,86614},["note"]="Use the remaining hunting/shores tasks to finish the zone. Vyrin's named target can hit hard; skip rather than force an unsafe solo pull. Train and choose your next 20+ route afterward."}}},{["id"]="darkshore",["name"]="Darkshore",["faction"]="Alliance",["min"]=10,["max"]=20,["area"]=148,["hubs"]={{["name"]="Auberdine and southern coast",["min"]=10,["max"]=12,["quests"]={983,1001,3524,4681,2118},["note"]="Set Auberdine as your home and collect coastal/buzzbox work. Keep required crab and other shore drops; bring washed-ashore discoveries back during the return leg."},{["name"]="Ruins and nearby forest",["min"]=12,["max"]=14,["quests"]={954,955,956,957,953,958,963,984,985,1141},["note"]="Take the Bashal'Aran and Ameth'Aran tasks before visiting either ruin. Complete their chains in order and combine forest targets with the return to Auberdine."},{["name"]="Cliffspring and crystal",["min"]=14,["max"]=16,["quests"]={1002,4761,4762,4811,4812,4813,2138},["note"]="Make the northern river/crystal circuit. Carry the container when the current quest supplies one, then return before starting the crystal's next stage."},{["name"]="Onu and the south",["min"]=16,["max"]=18,["quests"]={1003,944,948,949,950,947,2139},["note"]="Work south through the Master's Glaive to Onu. Take the twilight and cave-mushroom objectives together, avoiding deep cave pulls when your level is low."},{["name"]="Northern discoveries and departure",["min"]=18,["max"]=20,["quests"]={982,951,1138,2098,2078,986,993},["note"]="Finish safe northern/coastal discoveries. Underwater wrecks and Gyromast's target deserve caution or a group. Track optional dungeon quests separately, then take the road toward Ashenvale."}}},{["id"]="barrens",["name"]="The Barrens",["faction"]="Horde",["min"]=10,["max"]=20,["area"]=17,["hubs"]={{["name"]="Crossroads",["min"]=10,["max"]=12,["quests"]={844,871,5041,869,845,870,848},["note"]="Set your home at the Crossroads and pick up its first loops together. Work northeast for quillboar supplies, gather beast drops on the road, and inspect the oasis after its pickup."},{["name"]="Ratchet and the coast",["min"]=12,["max"]=14,["quests"]={1492,887,890,892,888,895},["note"]="Visit Ratchet for its flight connection and coastal work. Clear pirates and recover shipment goods together; Baron Longshore is a named target, not an excuse to pull his whole camp."},{["name"]="Kolkar and beasts",["min"]=14,["max"]=16,["quests"]={850,855,903,881,905,877,880},["note"]="Work the western oasis and centaur camps before returning. Keep the supplied horn for Echeyakee and use it at the requested location. Follow oasis stages in order."},{["name"]="Northern machinery and harpies",["min"]=15,["max"]=18,["quests"]={894,900,901,902,867,875,876,3921,3922},["note"]="Take the Samophlange machinery stages in sequence while working the northern harpy loop. Serena is optional if unsafe; finish the machinery reports before expecting the later manual chain."},{["name"]="Southern Barrens",["min"]=18,["max"]=20,["quests"]={3261,865,907,913,899,4921,891},["note"]="Visit Camp Taurajo and collect the southern beast work together. Keep raptor horns for the optional Wailing Caverns quest. Northwatch can be dangerous: seek a group or skip. Finish reports before moving into Stonetalon/Ashenvale."}}},{["id"]="silverpine",["name"]="Silverpine Forest",["faction"]="Horde",["min"]=10,["max"]=20,["area"]=130,["hubs"]={{["name"]="Sepulcher and northern road",["min"]=10,["max"]=12,["quests"]={3221,447,428,429,430,449,6321,6322,6323,6324},["note"]="Set up the Sepulcher and its flight connection. Gather the first death/plague tasks while following the northern road and recover the missing scouts before returning."},{["name"]="Ivar and the dead fields",["min"]=12,["max"]=14,["quests"]={425,435,437,422,423},["note"]="Visit Ivar's farm and the Dead Fields on one loop. Start escorts only after clearing the road. Follow Arugal's stages after each report rather than entering a later camp prematurely."},{["name"]="Ambermill",["min"]=14,["max"]=16,["quests"]={477,478,481,482,479,424,99},["note"]="Work the border-crossing and Ambermill intelligence tasks in order. Use the town edges for safe pulls and return to the Sepulcher when a report unlocks the next stage."},{["name"]="Ferry and rot hides",["min"]=16,["max"]=18,["quests"]={438,439,440,441,443,444,446,448},["note"]="Take the ferry/rot-hide clues together, then carry the ring report into the Undercity as instructed. Return with the follow-up before clearing Ravenclaw targets."},{["name"]="Final investigations",["min"]=18,["max"]=20,["quests"]={450,451,460,461,491,530,493},["note"]="Finish the apothecary and hidden-niche chains. Pyrewood/Shadowfang content stays optional in the Dungeon manager. Deliver the Hillsbrad breadcrumb when ready to leave at twenty."}}},{["id"]="redridge",["name"]="Redridge Mountains",["faction"]="Alliance",["min"]=15,["max"]=20,["area"]=44,["hubs"]={{["name"]="Lakeshire setup",["min"]=15,["max"]=16,["quests"]={244,129,130,131,116,3741},["note"]="Set up Lakeshire and clear the road gnolls before the first return. Dry Times sends you to several vendors: obtain the requested drinks during city/Westfall visits rather than making a separate trip for each. Recover Hilary's necklace only with enough breath and a safe shore."},{["name"]="Northern slopes",["min"]=16,["max"]=18,["quests"]={246,98407,125},["note"]="Combine mongrels, poachers and collars on the northern circuit. Recover the toolbox at its marked location and return the tools before the bridge materials stage."},{["name"]="Farm and hunting errands",["min"]=18,["max"]=19,["quests"]={92,118,119,122},["note"]="Gather the goulash ingredients together while finishing hunting targets. Deliver Verner's shoe report and return with the follow-up on the same Elwynn visit."},{["name"]="Bridge and eastern edge",["min"]=19,["max"]=20,["quests"]={89,124,150},["note"]="Collect bridge materials and safe eastern/shore objectives before tackling the later elite camps. This route stops at twenty; the tower and higher-level named elites are deliberately outside it."}}},{["id"]="stonetalon",["name"]="Stonetalon Mountains",["faction"]="Horde",["min"]=15,["max"]=20,["area"]=406,["hubs"]={{["name"]="Malaka'jin approach",["min"]=15,["max"]=17,["quests"]={6548,6629,6523,6401},["note"]="Gather the village-revenge and Kaya tasks before entering the camp. Clear the escort path first; if the event is unavailable, skip it and continue the road circuit."},{["name"]="Windshear approaches",["min"]=17,["max"]=19,["quests"]={1061,1062,1063,6461},["note"]="Combine goblin and spider work on the Windshear edge. Report the spirits chain through its next hub and stay out of dense logging-camp packs until your level is suitable."},{["name"]="Boulderslide and departure",["min"]=19,["max"]=20,["quests"]={6421,6481},["note"]="Visit the ravine only after accepting the crystal investigation. Complete its follow-up before leaving. Higher-level Venture Co. and charred-vale tasks belong in the next route."}}},{["id"]="ashenvale-alliance",["name"]="Ashenvale",["faction"]="Alliance",["min"]=18,["max"]=20,["area"]=331,["hubs"]={{["name"]="Astranaar arrival",["min"]=18,["max"]=19,["quests"]={990,991},["note"]="Follow the road from Darkshore into Astranaar and establish the flight connection. Begin Raene's investigation, returning its reports before expecting later cleansing stages."},{["name"]="Zoram Strand",["min"]=19,["max"]=20,["quests"]={1008,1007},["note"]="Take the coastal naga and statuette work together. Sweep the strand once and return inland; optional Blackfathom quests live in the Dungeon manager."},{["name"]="Bathran's Haunt",["min"]=20,["max"]=20,["quests"]={1010,1020,1056},["note"]="Collect the hair at the named haunted area and deliver the cure afterward. The Stonetalon travel report is optional; this chapter ends before the zone's higher-level chains."}}},{["id"]="ashenvale-horde",["name"]="Ashenvale",["faction"]="Horde",["min"]=18,["max"]=20,["area"]=331,["hubs"]={{["name"]="Warsong road",["min"]=18,["max"]=19,["quests"]={6541,6543,6545},["note"]="Collect the Warsong report stages at the border and follow each messenger along the road. Avoid Alliance settlements and use the outpost paths."},{["name"]="Zoram'gar",["min"]=19,["max"]=20,["quests"]={6442},["note"]="Visit the western Horde outpost and establish its flight connection before clearing naga along the strand. Blackfathom is optional through the Dungeon manager."},{["name"]="The hunt begins",["min"]=20,["max"]=20,["quests"]={6382,6383},["note"]="Deliver the Ashenvale Hunt introduction when you reach twenty. Its named hunting targets extend beyond this guide's level range; use the next route rather than chasing them underlevelled."}}},{["id"]="duskwood",["name"]="Duskwood",["faction"]="Alliance",["min"]=20,["max"]=30,["area"]=10,["hubs"]={{["name"]="Darkshire and Raven Hill",["min"]=20,["max"]=23,["quests"]={56,5,93,163,164,226,245,96139},["note"]="Start in Darkshire, gather the Night Watch and food tasks, then follow the road to Raven Hill and Sven. Combine wolves and spiders on the journey. Return to town to unlock the next Night Watch stage before pushing into the cemetery."},{["name"]="The hermit and the cemetery",["min"]=23,["max"]=25,["quests"]={57,90,101,165,148,149,154,157,158,156,159,174,175,177,96137},["note"]="Visit the hermit and follow his supply errands through Darkshire and the graveyard. Keep the thread and juice deliveries in their quest order; collect rot blossoms during the cemetery circuit. Look To The Stars needs a bronze tube: obtain one before that stage, or skip it."},{["name"]="Sven and the shadowy figure",["min"]=25,["max"]=28,["quests"]={95,230,262,265,266,453,268,323,269,270,321,324,322,325},["note"]="Continue Sven’s investigation after his earlier deliveries. Follow the inn and witness reports before returning to Sven. The later investigation travels to Stormwind and Menethil: finish local turn-ins before the trip, then follow live markers for the fleet and iron objectives."},{["name"]="Southern woods and final reports",["min"]=28,["max"]=30,["quests"]={173,221,58,133,134,160,251,401,252,253,181,96138},["note"]="Work the worgen stages from Darkshire and complete remaining hermit reports in sequence. The last Night Watch stage, Bride of the Embalmer and the final telescope target can be dangerous; use a group or Skip. Finish local reports before choosing the next zone from Library."}}},{["id"]="wetlands",["name"]="Wetlands",["faction"]="Alliance",["min"]=20,["max"]=30,["area"]=11,["hubs"]={{["name"]="Menethil and the road",["min"]=20,["max"]=22,["quests"]={455,469,484,279,463,276,98459,98461},["note"]="Establish Menethil’s flight connection and collect the town’s coast and road tasks. Travel east to the Greenwarden while gathering crocolisk skins; complete the first gnoll stage before expecting Fire Taboo. Follow live markers for Forever’s local errands."},{["name"]="Greenwarden and excavation",["min"]=22,["max"]=25,["quests"]={277,275,305,306,294,470,281,284,285,98189,98282},["note"]="Return the Greenwarden’s first tasks, then visit the excavation team. Combine raptor work with the nearby ooze collection. Follow the missing-goods hovel chain in order; the installed Forever database uses its own Return the Statuette quest."},{["name"]="Raptors and the wrecks",["min"]=25,["max"]=28,["quests"]={295,299,288,289,471,473,464,98197},["note"]="Advance Ormer’s hunt only after reporting the previous stage. Gather excavation relics during that loop, then return to Menethil for the Third Fleet and cursed crew. Bring the requested drink for the fleet conversation; collect banners after Captain Stoutfist’s report."},{["name"]="Final hunts and Dun Modr",["min"]=28,["max"]=30,["quests"]={296,290,292,293,472,303,98245,98246,98293},["note"]="Finish the raptor and wreck chains when the targets are manageable. Dun Modr and some named targets are group work: Skip if a group is unavailable. Complete the Forever follow-ups indicated by live quest availability before moving on; turn in at Menethil on the return journey."}}},{["id"]="ashenvale-alliance-20",["name"]="Ashenvale",["faction"]="Alliance",["min"]=20,["max"]=30,["area"]=331,["hubs"]={{["name"]="Astranaar continuation",["min"]=20,["max"]=23,["quests"]={991,1023,1024,1010,1020,1033,1034},["note"]="Continue from the earlier Ashenvale guide at Astranaar. Completed introductions are skipped automatically; newcomers should finish Raene’s initial reports and Bathran’s cure. Work Elune’s Tear before the Ruins of Stardust and return each part to unlock the next."},{["name"]="Western and central forest",["min"]=23,["max"]=25,["quests"]={1007,1009,1016,1017,1025,1054},["note"]="Finish the coastal statuette pickup before its named target. Work the coast and central elemental objectives with the live markers, then clear the aggressive furbolg and culling tasks. Avoid Horde settlements while crossing the zone."},{["name"]="Raene’s investigation",["min"]=25,["max"]=28,["quests"]={1026,1027,1028,1055,1029,1030},["note"]="Follow Raene’s reports in order, checking the current quest giver after each hand-in. Several stages send you back through earlier parts of the forest; combine travel with unfinished central quests and do not expect later stages before their prerequisites."},{["name"]="Eastern forest",["min"]=28,["max"]=30,["quests"]={4581,1011,1022,1035,1045,1046},["note"]="Visit Kayneth for the eastern disease investigation and work Howling Vale and Fallen Sky Lake when safe. Finish Raene’s final reports after the cleansing stages. Named enemies can require help; Skip unsafe objectives and select the next route manually in Library."}}},{["id"]="ashenvale-horde-20",["name"]="Ashenvale",["faction"]="Horde",["min"]=20,["max"]=30,["area"]=331,["hubs"]={{["name"]="Warsong and Zoram’gar",["min"]=20,["max"]=23,["quests"]={6383,6503,6547,6641},["note"]="Finish the hunt introduction at Splintertree and establish the Zoram’gar flight connection. Take Outrunners and the scout report along the road. Vorsha is an encounter with waves: clear the area first and skip if you cannot safely complete it."},{["name"]="Thistlefur and the hunt",["min"]=23,["max"]=25,["quests"]={23,216,6462,6482,6544,6546},["note"]="Combine Thistlefur work and charms on one circuit. Ursangous is a roaming hunt target; use live quest markers rather than waiting at one guessed spawn. Ruul and Torek are escorts: prepare a clear route and skip them if the event is unavailable."},{["name"]="Satyrs and Warsong supplies",["min"]=25,["max"]=28,["quests"]={24,6441,6621,6571,6581,1918,824},["note"]="Continue the hunt with Shadumbra while clearing satyr and Foulweald tasks. Gather the Warsong supplies requested by the current step and report the befouled element to Je’neu at Zoram’gar. Return each report before attempting its follow-up."},{["name"]="Sharptalon and closing reports",["min"]=28,["max"]=30,["quests"]={2,247,6504,25},["note"]="Hunt Sharptalon when you can handle the encounter and finish The Hunt Completed after all three trophies. Collect the lost pages as you work the eastern forest; avoid buying pages unless you choose to. Report the Stonetalon standstill and select your next route from Library."}}},{["id"]="stonetalon-alliance-20",["name"]="Stonetalon Mountains",["faction"]="Alliance",["min"]=20,["max"]=28,["area"]=406,["hubs"]={{["name"]="The border and Gaxim",["min"]=20,["max"]=22,["quests"]={1070,1085,1071,1072,1075,1076,1077,1073,1074},["note"]="Follow the Ashenvale border reports to Gaxim. His supply chain includes a Stormwind conversation and Westfall collection: group those errands into one trip before returning. The chemistry stages unlock in order; finish their turn-ins before the next chapter."},{["name"]="Windshear work",["min"]=22,["max"]=25,["quests"]={1079,1080,1091,1093,1094,79980},["note"]="Work the two Covert Ops assignments around Windshear and return the reports. Super Reaper starts a separate instruction chain; take it only when the live giver offers it. Follow the current markers for Forever’s Scramble task, then clear remaining local pickups."},{["name"]="Charred Vale and northern reports",["min"]=25,["max"]=28,["quests"]={1078,1083,1057,1059,1084,1082,1081,1095,1096,86574},["note"]="Move into the Charred Vale after your earlier reports and gather the requested creatures and spirits together. Complete the Reclaiming chain and wounded ancients before the long final report. Named targets may need a group; finish supplies and select another 20–30 route for remaining experience."}}},{["id"]="stonetalon-horde-20",["name"]="Stonetalon Mountains",["faction"]="Horde",["min"]=20,["max"]=29,["area"]=406,["hubs"]={{["name"]="Sun Rock continuation",["min"]=20,["max"]=23,["quests"]={1093,1094,1062,1068,1090,1092,6301,6284,79980},["note"]="Continue from Sun Rock Retreat and collect the Windshear assignments before travelling east. Gerenzo’s Orders begins from the encountered quest giver and includes an event; check availability in the world. Work Super Reaper and the early replanting tasks on this circuit."},{["name"]="Rebirth and the vale",["min"]=23,["max"]=26,["quests"]={6381,6393,1087,1058,6282,6283,86576,97538},["note"]="Return the seeds before planting New Life, then combine the elemental and harpy work in the Charred Vale. Follow live locations for the Forever trinket and pigment tasks. Keep Jin’Zil’s collection until all requested forest materials are ready."},{["name"]="Windshear and northern targets",["min"]=26,["max"]=29,["quests"]={1095,1096,1088,1089,5881},["note"]="Complete Further Instructions and Gerenzo’s machinery before travelling north for Ordanus and The Den. These named encounters can be difficult: use help or Skip. Finish the reserve report and use Library to continue in Ashenvale, Hillsbrad or Thousand Needles."}}},{["id"]="hillsbrad-horde",["name"]="Hillsbrad Foothills",["faction"]="Horde",["min"]=20,["max"]=30,["area"]=267,["hubs"]={{["name"]="Tarren Mill arrival",["min"]=20,["max"]=23,["quests"]={494,549,498,496,499},["note"]="Establish Tarren Mill’s flight connection and take the Syndicate, rescue and first elixir tasks. Clear the nearby camps before attempting the rescue. Turn in Elixir of Suffering to unlock its next stage; the battle chain is a separate trip to Hillsbrad."},{["name"]="Hillsbrad farms",["min"]=23,["max"]=25,["quests"]={527,528,546,501,502},["note"]="Begin Battle of Hillsbrad at the farms, returning to Tarren Mill between stages. Collect Souvenirs of Death during these visits and complete the pain elixir in sequence. Avoid Southshore guards and keep a safe retreat from clustered farm enemies."},{["name"]="The town and mine",["min"]=25,["max"]=28,["quests"]={529,532,539,509,513},["note"]="Advance the battle through its town and mine reports after each hand-in. Start the agony elixir once offered and bring its collection back before the next stage. Work one building or mine section at a time; return to train when difficulty outpaces your equipment."},{["name"]="Final orders",["min"]=28,["max"]=30,["quests"]={541,515,517,524,567,547},["note"]="Finish the battle and agony chains in their given order. Dangerous and Humbert’s Sword involve named enemies or contested camps; use a group or Skip when unsafe. Complete the reports at Tarren Mill, then select your next route manually rather than following Alliance coastal quests."}}},{["id"]="thousand-needles-horde",["name"]="Thousand Needles",["faction"]="Horde",["min"]=23,["max"]=30,["area"]=400,["hubs"]={{["name"]="Freewind Post",["min"]=23,["max"]=25,["quests"]={4542,4841,4821,4865},["note"]="Enter from the southern Barrens and establish the Freewind Post flight connection. Deliver the introduction, then combine centaur work, the alien egg and serpent objectives. Stay on safe paths between mesas and return to the post before advancing the chains."},{["name"]="Sacred fire and Grimtotem",["min"]=25,["max"]=28,["quests"]={5062,5088,5064,4881,4966,1149},["note"]="Begin Sacred Fire before its summoned encounter. Gather Grimtotem intelligence and follow the assassination warning before protecting Kanati. Complete Test of Faith with the actual quest instructions; use a group or Skip for encounters beyond your current strength."},{["name"]="Escorts and northern reports",["min"]=28,["max"]=29,["quests"]={4767,4770,4904,5147},["note"]="Work Wind Rider and the northern named target while gathering the escort pickups. Homeward Bound and Free at Last depend on events being available: clear their paths, keep escorts together and skip when unavailable rather than waiting indefinitely."},{["name"]="Shimmering Flats",["min"]=29,["max"]=30,["quests"]={5151,1104,1105,1176},["note"]="Finish the Hypercapacitor follow-up after its prerequisites, then travel to the Shimmering Flats for venom, shells and load-lightening. Gather these together around the raceway and return in one circuit. These routes stop at thirty; choose further content from the map when complete."}}},{["id"]="redridge-alliance-20",["name"]="Redridge Mountains",["faction"]="Alliance",["min"]=20,["max"]=27,["area"]=44,["hubs"]={{["name"]="Lakeshire and the lake",["min"]=20,["max"]=22,["quests"]={125,89,127,150,98386,98387},["note"]="Return to Lakeshire and collect the bridge, fishing and Blackrock tasks before leaving town. Finish any earlier deliveries exposed by this chapter; completed introductions skip automatically. Combine murlocs and bridge materials around Lake Everstill, then return to repair the bridge before the northern circuit."},{["name"]="Northern camps and the watchtower",["min"]=22,["max"]=25,["quests"]={118,119,124,126,20,115,91,94,248,34},["note"]="Gather the northern gnoll and Blackrock assignments together. Complete Blackrock Menace before Shadow Magic, and return the watchtower report before Looking Further. Clear the approaches before entering camps; Bellygrub is a separate western visit, best combined with a town return."},{["name"]="Blackrock strongholds",["min"]=25,["max"]=27,["quests"]={19,128,219,169,180,178,249,95999},["note"]="Finish the named Blackrock and gnoll targets only when the camps are manageable. Missing In Action is an escort: clear its exit before starting. Gath’Ilzogg, Morganth and other stronghold targets may need help; Skip unsafe encounters. Turn in at Lakeshire, then choose Duskwood or Wetlands for the rest of the twenties."}}},{["id"]="barrens-horde-20",["name"]="The Barrens",["faction"]="Horde",["min"]=20,["max"]=30,["area"]=17,["hubs"]={{["name"]="Crossroads and Ratchet follow-ups",["min"]=20,["max"]=22,["quests"]={867,875,876,1060,850,851,852,4021,891,898,92706,4921,95774},["note"]="Finish any missing Crossroads introductions before their final hunts. Take Ratchet’s Northwatch work together and clear the fort before starting the rescue escort. Counterattack and wanted targets are optional group encounters. Report Mankrik’s search and memorial tasks when offered; return reports before moving south."},{["name"]="Camp Taurajo and the southern road",["min"]=22,["max"]=24,["quests"]={878,5052,899,844,845,903,881,905,3261,882,907,913,874,868,843,883,97003,97250,98093},["note"]="Use Camp Taurajo as the southern hub. Gather quillboar tusks while completing Tribes at War, then deliver the Blood Shard before expecting Betrayal. Combine the thunderhawk report, silithid eggs and Gann’s first excavation task along the road. Named beasts start item quests only when their drops are found; Skip absent drops rather than waiting."},{["name"]="Bael Modan and the coast",["min"]=24,["max"]=27,["quests"]={879,906,893,846,849,873,819,821,822,884,885,897},["note"]="Return to Gann between each demolition stage and carry the betrayal report back to the Crossroads. Combine Weapons of Choice with the southern camps, then visit the coast for Isha Awak. Chen’s final collection needs earlier keg deliveries; the chapter includes those if unfinished. Do not farm named quest starters indefinitely."},{["name"]="Final hunts and onward travel",["min"]=27,["max"]=30,["quests"]={1153,857,3513,3514,6382},["note"]="Take the ore-sample follow-up after Weapons of Choice and work Bael Modan’s deeper target with help if needed. The Runed Scroll begins from a drop and sends you into Stonetalon; complete its tower report before the Talon Den encounter. Finish the Ashenvale introduction, then select Ashenvale or Thousand Needles in Library."}}},{["id"]="silverpine-horde-20",["name"]="Silverpine Forest",["faction"]="Horde",["min"]=20,["max"]=24,["area"]=130,["hubs"]={{["name"]="Sepulcher reports and the roads",["min"]=20,["max"]=21,["quests"]={437,438,439,440,441,530,95981,98299,493},["note"]="Return to the Sepulcher for unfinished reports and the road watch. Earlier delivery stages appear only if you have not completed them. Take the Hillsbrad introduction before leaving, but finish the remaining Silverpine loops first. Follow the live giver for Stop the Spread rather than treating its missing recorded starter as a confirmed offer."},{["name"]="Ambermill and Beren’s Peril",["min"]=21,["max"]=23,["quests"]={477,478,481,482,479,480,516,95883,95884,95885},["note"]="Finish the Ambermill investigation before confronting the Weaver. Work Beren’s Peril on the same eastern circuit and inspect the Tortured Soul item before looking for the Offering Stone. These Forever stages have incomplete starter metadata: use the live quest instructions and Skip a step that is not offered."},{["name"]="Fenris Isle and Hillsbrad departure",["min"]=23,["max"]=24,["quests"]={443,444,446,448,442},["note"]="Finish the recorded Fenris investigation reports before the island assault. Clear the approach and bring help for dense camps; Skip the assault if unsafe. Return the final report to the Sepulcher, then select Hillsbrad Foothills in Library. This continuation finishes early in the twenties rather than promising a route to thirty."}}},{["id"]="loch-modan-alliance-20",["name"]="Loch Modan",["faction"]="Alliance",["min"]=20,["max"]=30,["area"]=38,["hubs"]={{["name"]="The dam and northern reports",["min"]=20,["max"]=21,["quests"]={250,199,161,274,278,280,283,86614},["note"]="Finish the dam investigation in its actual report order, carrying the disarming mixture only after its collection stages. Check the lake for Silver of the Waves if its item is available. Return each report before moving on; completed lower-level introductions skip automatically."},{["name"]="Farstrider Lodge and Chok’sul",["min"]=21,["max"]=23,["quests"]={257,258,271,531,256},["note"]="Visit Farstrider Lodge and finish the hunting introduction before Vyrin’s revenge. Ol’ Sooty and Chok’sul can be difficult: clear nearby enemies and use a group or Skip. Return the trophy and final conversation before choosing Wetlands for the main part of the twenties."},{["name"]="Optional forge return",["min"]=28,["max"]=30,["quests"]={86776},["note"]="This is a short optional return to Thelsamar, not a leveling circuit from twenty-three to twenty-eight. Ingredients for the Forge asks for ten Bronze Bars; bring them only if you choose the quest and the live giver offers it. Do not buy supplies merely because this chapter is visible. Select Wetlands or Duskwood for remaining experience."}}},{["id"]="darkshore-alliance-20",["name"]="Darkshore",["faction"]="Alliance",["min"]=20,["max"]=28,["area"]=148,["hubs"]={{["name"]="Auberdine and the northern coast",["min"]=20,["max"]=21,["quests"]={947,948,944,949,950,951,2098,2078,87760,98013,98028},["note"]="Finish Onu’s earlier reports before collecting Mathystra relics, then combine the northern coast work with Gyromast’s retrieval. His revenge is a separate dangerous encounter: clear the area and Skip if help is unavailable. Follow live markers for Forever’s coastal tasks and return to Auberdine before travelling south."},{["name"]="Southern escorts and the lost master",["min"]=21,["max"]=24,["quests"]={984,985,986,993,994,5321,729,731,741,942,943,968},["note"]="Gather the lost-master reports and southern escort tasks before travelling. This route chooses Escape Through Force; if you already completed the alternate escape, use Skip for the unavailable branch. Clear escort paths first. The prospector’s follow-ups travel outside Darkshore, so finish local reports before the trip and use live destinations."},{["name"]="Althalaxx and Ashenvale",["min"]=24,["max"]=28,["quests"]={965,966,967,970,973,1140,1167},["note"]="Finish the tower’s earlier delivery stages before the later Althalaxx investigation. This chain crosses into Ashenvale and returns through its contacts; hand in each report before expecting the next. Bring help for difficult tower targets or Skip them. Select the Ashenvale continuation for the rest of the twenties."}}},{["id"]="thousand-needles-alliance",["name"]="Thousand Needles",["faction"]="Alliance",["min"]=28,["max"]=30,["area"]=400,["hubs"]={{["name"]="Theramore and Highperch",["min"]=28,["max"]=29,["quests"]={1132,1135},["note"]="Take Fiora Longears’ introduction at Menethil if unfinished, then visit her in Theramore for Highperch Venom. Travel into Thousand Needles without entering Horde settlements. Gather venom at Highperch with a safe retreat from the cliffs; return it to Fiora when convenient before the raceway circuit."},{["name"]="The Shimmering Flats",["min"]=29,["max"]=30,["quests"]={1179,1104,1105,1176},["note"]="Pick up the Brassbolts delivery in Ironforge before the journey if available. At the raceway, gather venom, tortoise shells and vulture bones together and return the collections in one circuit. Freewind Post’s Horde quests are excluded. This is a late-twenties visit; select another zone if the minimum-level tasks are not yet available."}}},{["id"]="hillsbrad-alliance-30",["name"]="Hillsbrad Foothills",["faction"]="Alliance",["min"]=25,["max"]=30,["area"]=267,["kind"]="detour",["hubs"]={{["name"]="Southshore coast",["min"]=25,["max"]=30,["quests"]={536},["note"]="Optional visit: establish Southshore’s flight connection and take Down the Coast from Lieutenant Farren Orinelle. Clear the Torn Fin camps along the shore, avoiding Tarren Mill guards. The next coastal stage is above this guide’s level range in the installed Forever data; turn in and choose another Library route rather than expecting a complete twenty-to-thirty circuit here."}}},{["id"]="westfall-alliance-20",["name"]="Westfall",["faction"]="Alliance",["min"]=20,["max"]=22,["area"]=40,["kind"]="detour",["hubs"]={{["name"]="The lighthouse and the strange note",["min"]=20,["max"]=22,["quests"]={104,79008},["note"]="Optional return: finish the lighthouse’s Old Murk-Eye hunt when the target is safe, then inspect the strange note only if you find its quest object. Follow the live text for the note’s destinations; its presence is not guaranteed. Turn in remaining Westfall reports and select Duskwood or Wetlands rather than staying here for a full twenties route."}}},{["id"]="dun-morogh-alliance-20",["name"]="Dun Morogh",["faction"]="Alliance",["min"]=20,["max"]=23,["area"]=1,["kind"]="detour",["hubs"]={{["name"]="Stonegear’s incendicite errand",["min"]=20,["max"]=23,["quests"]={467,466},["note"]="Optional collection trip: speak to Pilot Stonegear after the search introduction and take Search for Incendicite. The ore collection sends you to Wetlands, so combine it with that journey rather than treating Dun Morogh as a twenties leveling zone. Bring the ore back when convenient and use Library to return to your main route."}}},{["id"]="dustwallow-alliance-30",["name"]="Dustwallow Marsh",["faction"]="Alliance",["min"]=25,["max"]=30,["area"]=15,["kind"]="detour",["hubs"]={{["name"]="Fiora and the Highperch trip",["min"]=25,["max"]=30,["quests"]={1132,1135},["note"]="Optional Theramore visit: follow Fiora’s Menethil introduction if unfinished, then take Highperch Venom. Its collection takes place in Thousand Needles; gather the sacs on that trip and return to Fiora. Avoid wandering into higher-level marsh camps. This detour shares quests with the Alliance Thousand Needles guide; native completion history prevents repeating the hand-ins."}}},{["id"]="stranglethorn-alliance-30",["name"]="Stranglethorn Vale",["faction"]="Alliance",["min"]=28,["max"]=30,["area"]=33,["kind"]="detour",["hubs"]={{["name"]="Nesingwary’s introduction",["min"]=28,["max"]=30,["quests"]={583},["note"]="Optional arrival: speak to Barnil Stonepot and deliver Welcome to the Jungle to Hemet Nesingwary. Avoid dense camps while approaching the expedition. The installed Forever data places the hunting follow-ups above this guide’s range, so this is an introduction only. Finish your current twenties route before treating Stranglethorn as the next leveling circuit."}}},{["id"]="stranglethorn-horde-30",["name"]="Stranglethorn Vale",["faction"]="Horde",["min"]=28,["max"]=30,["area"]=33,["kind"]="detour",["hubs"]={{["name"]="Nesingwary’s introduction",["min"]=28,["max"]=30,["quests"]={583},["note"]="Optional arrival: speak to Barnil Stonepot and deliver Welcome to the Jungle to Hemet Nesingwary. Avoid dense camps while approaching the expedition. The installed Forever data places the hunting follow-ups above this guide’s range, so this is an introduction only. Finish your current twenties route before treating Stranglethorn as the next leveling circuit."}}},{["id"]="barrens-alliance-20",["name"]="The Barrens",["faction"]="Alliance",["min"]=20,["max"]=24,["area"]=17,["kind"]="detour",["hubs"]={{["name"]="Ratchet and the Windshear errand",["min"]=20,["max"]=22,["quests"]={1069,1483,1093,1094},["note"]="Optional neutral-hub trip: visit Ratchet for the Deepmoss collection and Ziz Fizziks introduction, then combine the eggs with a Windshear visit in Stonetalon. Complete Super Reaper’s report before Further Instructions. Avoid Horde settlements; this is not the Horde Camp Taurajo route."},{["name"]="Southern wanted target and the note",["min"]=22,["max"]=24,["quests"]={97005,79192},["note"]="Take the Alliance version of Chol’aruk’s wanted task only when its live giver offers it. Bring help for a difficult named target or Skip. Stepping Stones begins at a found note; follow its live instructions rather than waiting for an ordinary NPC pickup. Return to an Alliance route in Library when these optional errands are complete."}}}},{["2"]={["title"]="Sharptalon's Claw",["level"]=30,["min"]=20},["5"]={["title"]